          <h2 className="mb-1 font-medium text-neutral-500">Priority</h2>
          <Badge tone={PRIORITY_TONE[issue.priority]}>
            {humanizePriority(issue.priority)}
          </Badge>
        </section>

        <section>
          <h2 className="mb-1 font-medium text-neutral-500">Assignee</h2>
