const zoneFormatters = new Map<string, Intl.DateTimeFormat>();

function zoneFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = zoneFormatters.get(timeZone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      calendar: "iso8601",
      numberingSystem: "latn",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    });
    zoneFormatters.set(timeZone, formatter);
  }
  return formatter;
}

/** Throws RangeError before a settings update can persist an unknown zone. */
export function assertTimeZone(timeZone: string): void {
  zoneFormatter(timeZone);
}

function localParts(reference: Date, timeZone: string): Record<string, string> {
  return Object.fromEntries(
    zoneFormatter(timeZone).formatToParts(reference).map(({ type, value }) => [type, value]),
  );
}

/** The calendar date of an instant on a workspace's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const { year, month, day } = localParts(parseIso(value), timeZone);
  return `${year.padStart(4, "0")}-${month}-${day}`;
}

/** Calendar arithmetic on a date, independent of the length of a zoned day. */
export function addCalendarDays(day: string, days: number): string {
  const date = new Date(`${day}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function wallTime(reference: Date, timeZone: string): number {
  const parts = localParts(reference, timeZone);
  return new Date(
    `${parts.year.padStart(4, "0")}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}.000Z`,
  ).getTime();
}

/**
 * Invert Intl's clock using the offsets on either side of the requested day.
 * A repeated hour has two instants. A skipped hour resolves to the transition,
 * the first available local time after it (also handles skipped midnights).
 */
function localHourInstants(day: string, hour: number, timeZone: string): number[] {
  const target = new Date(`${day}T${String(hour).padStart(2, "0")}:00:00.000Z`).getTime();
  const offsets = new Set<number>();
  for (let hours = -48; hours <= 48; hours += 12) {
    const sample = target + hours * HOUR_MS;
    offsets.add(wallTime(new Date(sample), timeZone) - sample);
  }
  const candidates = [...offsets].map((offset) => target - offset).sort((a, b) => a - b);
  const matches = candidates.filter((instant) => wallTime(new Date(instant), timeZone) === target);
  if (matches.length > 0) return matches;

  let low = candidates[0];
  let high = candidates[candidates.length - 1];
  while (high - low > 1) {
    const middle = Math.floor((low + high) / 2);
    if (wallTime(new Date(middle), timeZone) < target) low = middle;
    else high = middle;
  }
  return [high];
}

/** UTC instant at which a calendar date begins in the given zone. */
export function startOfLocalDate(day: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(new Date(localHourInstants(day, 0, timeZone)[0]));
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return startOfLocalDate(localDate(toIsoTimestamp(reference), timeZone), timeZone);
}

/** A due date becomes overdue only after its entire local calendar day. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * One local calendar day's digest window, ending at the most recent local
 * digest hour. Its elapsed length may be 23 or 25 hours across DST.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  let endDay = localDate(toIsoTimestamp(reference), timeZone);
  let end = localHourInstants(endDay, digestHourUtc, timeZone)
    .filter((instant) => instant <= reference.getTime()).at(-1);
  if (end === undefined) {
    endDay = addCalendarDays(endDay, -1);
    end = localHourInstants(endDay, digestHourUtc, timeZone).at(-1)!;
  }

  return {
    start: toIsoTimestamp(new Date(localHourInstants(addCalendarDays(endDay, -1), digestHourUtc, timeZone).at(-1)!)),
    end: toIsoTimestamp(new Date(end)),
  };
}
